import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { cssVariableSlug, walkTokens } from "./preprocess-tokens.mjs";

export { cssVariableSlug } from "./preprocess-tokens.mjs";

const __dirname = dirname(fileURLToPath(import.meta.url));
const packageDir = resolve(__dirname, "..");

const FILE_HEADER = `/* -------------------------------------------
 *  Autogenerated by @orca/token-pipeline. DO NOT EDIT!
 * ------------------------------------------- */`;

// Figma の textDecoration 値を CSS の text-decoration-line 値に変換する。
function cssTextDecorationLine(value) {
  if (value === "UNDERLINE") return "underline";
  if (value === "STRIKETHROUGH") return "line-through";
  return "none";
}

// Figma の textCase 値を CSS の text-transform 値に変換する。
function cssTextTransform(value) {
  if (value === "UPPER") return "uppercase";
  if (value === "LOWER") return "lowercase";
  if (value === "TITLE") return "capitalize";
  return "none";
}

// 1つの Figma Text style token を Tailwind v4 の @utility block に変換する。
function buildTypographyUtility(path, token) {
  const slug = cssVariableSlug(path);
  const value = token.$value ?? {};

  return [
    `@utility typography-${slug} {`,
    `  font-family: var(--${slug}-font-family);`,
    `  font-size: var(--${slug}-font-size);`,
    `  font-weight: var(--${slug}-font-weight);`,
    `  line-height: var(--${slug}-line-height);`,
    `  letter-spacing: var(--${slug}-letter-spacing);`,
    `  text-decoration-line: ${cssTextDecorationLine(value.textDecoration)};`,
    `  text-transform: ${cssTextTransform(value.textCase)};`,
    `}`
  ].join("\n");
}

// text style document 全体から typography-* utility CSS を生成する。
export function buildTypographyUtilities(document) {
  const utilities = [];

  walkTokens(document, (token, path) => {
    if (token.$type !== "typography") return;
    // 先頭 `_` のスタイル（例: _Doc/*）は Figma の内部/ドキュメント用。
    // 不正な Tailwind utility 名になるうえユーティリティ化すべきでないため除外する。
    if (path.some((segment) => segment.startsWith("_"))) return;
    utilities.push(buildTypographyUtility(path, token));
  });

  return `${FILE_HEADER}\n\n${utilities.join("\n\n")}\n`;
}

// CLI から呼ばれたときに text.json を読み、generated/typography-utilities.css を更新する。
export function generateTypographyUtilitiesFile({
  inputPath = resolve(packageDir, "tokens/styles/text.json"),
  outputPath = resolve(packageDir, "generated/typography-utilities.css")
} = {}) {
  const document = JSON.parse(readFileSync(inputPath, "utf8"));
  const css = buildTypographyUtilities(document);
  writeFileSync(outputPath, css);
  return outputPath;
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  generateTypographyUtilitiesFile();
}
